# Use a small node script with playwright to read #check
node <<'NODE'
const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 900, height: 700 } });
  await page.goto('file://' + process.cwd() + '/web/usability/compare-methods-not-algorithms.html');
  const check = await page.textContent('#check');
  const sw = await page.evaluate(() => document.documentElement.scrollWidth);
  console.log(check);
  console.log('scrollWidth', sw);
  // spot-check live index Match + Compare methods
  await page.goto('file://' + process.cwd() + '/web/index.html');
  const matchTitle = await page.getAttribute('label[title*="Match"]', 'title');
  const matchAria = await page.getAttribute('#epsilonInput', 'aria-label');
  const section = await page.textContent('.results-section-label');
  const labels = await page.$$eval('[aria-label*="Compare"]', els => els.map(e => e.getAttribute('aria-label')));
  const help = await page.textContent('.desktop-instructions');
  console.log({ matchTitle, matchAria, section: section?.trim().slice(0,80), labels, helpHasMethods: help?.includes('methods'), helpHasAlgo: help?.includes('algorithm') });
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
